import React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./ProgressBar.stories";
import ProgressBar from "./ProgressBar";

const { Basic } = composeStories(stories) as any;

describe("ProgressBar component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props to the root element", () => {
    render(<ProgressBar data-testid="progressbar" />);
    expect(screen.queryByRole("progressbar")).toHaveAttribute(
      "data-testid",
      "progressbar"
    );
  });
});
